from __future__ import annotations

import shutil
import tempfile
from dataclasses import dataclass, field
from pathlib import Path, PurePosixPath

from . import cabinet, cgd
from .manifest import NEW_SUFFIX, PackageFile, adler32_file, build_manifest, duplicate_basenames, \
    launcher_checksum_keys, parse_manifest
from .versions import GameVersion, PatchIni, package_name, parse_patch_ini, read_patch_ini

PRODUCT = 'microvolts'
CGD_PATH = PurePosixPath('data/cgd.dip')
REPAIR_FILES = (PurePosixPath('data/cgd.dip'), PurePosixPath('Bin/MicroVolts.exe'))
REFUSED = {
    'patch.ini': 'generated by this tool',
    'launcher.exe': 'the launcher cannot replace itself (file in use), ship a new launcher separately',
}
WARNED = {
    'updateinfo.ini': 'changes the update server every client (and the game version check) uses',
    'game.ini': "overwrites the player's own settings",
}


class BuildError(RuntimeError):
    pass


@dataclass
class BuildOptions:
    files_dir: Path
    tree: Path
    version: GameVersion | None = None
    client_root: Path | None = None
    cgd_password: bytes | None = None
    skip_cgd: bool = False
    require_existing: bool = False
    compression: str = 'MSZIP'
    legacy_patch_ini: bool = False


@dataclass
class BuildResult:
    source: GameVersion
    target: GameVersion
    cab: Path
    xml: Path
    files: list[PackageFile]
    warnings: list[str] = field(default_factory=list)


def product_root(tree: Path) -> Path:
    return tree / PRODUCT


def package_paths(tree: Path, source: GameVersion, target: GameVersion) -> tuple[Path, Path]:
    folder = product_root(tree) / str(target)
    name = package_name(PRODUCT, source, target)
    return folder / f'{name}.cab', folder / f'{name}.xml'


def current_patch(tree: Path) -> PatchIni:
    remote = product_root(tree) / 'patch.ini'
    if not remote.is_file():
        raise BuildError(f'{remote} does not exist: run "init" with the baseline client first')
    return read_patch_ini(remote)


def init_tree(tree: Path, client_root: Path, log=print) -> PatchIni:
    root = product_root(tree)
    if (root / 'patch.ini').exists():
        raise BuildError(f'{root / "patch.ini"} already exists')
    patch = read_patch_ini(client_root / 'patch.ini')
    _write(root / 'patch.ini', patch.render())
    launcher_ini = client_root / 'patchLauncher.ini'
    if launcher_ini.is_file():
        (root / 'Patcher').mkdir(parents=True, exist_ok=True)
        shutil.copyfile(launcher_ini, root / 'Patcher' / 'patchLauncher.ini')
    for rel in REPAIR_FILES:
        if (client_root / rel).is_file():
            (root / 'Full' / rel).parent.mkdir(parents=True, exist_ok=True)
            shutil.copyfile(client_root / rel, root / 'Full' / rel)
    log(f'(OK) tree initialised at baseline {patch.latest} ({len(patch.versions)} versions in history)')
    return patch


def collect_inputs(files_dir: Path) -> dict[PurePosixPath, Path]:
    if not files_dir.is_dir():
        raise BuildError(f'{files_dir} is not a directory')
    found = {}
    for path in sorted(files_dir.rglob('*')):
        if path.is_file():
            found[PurePosixPath(path.relative_to(files_dir).as_posix())] = path
    if not found:
        raise BuildError(f'{files_dir} contains no files')
    return found


def check_inputs(inputs: dict[PurePosixPath, Path], options: BuildOptions) -> list[str]:
    warnings = []
    lowered = {}
    for rel in inputs:
        key = rel.as_posix().lower()
        if key in lowered:
            raise BuildError(f'{rel} and {lowered[key]} differ only by case')
        lowered[key] = rel
        if rel.name.lower().endswith(NEW_SUFFIX):
            raise BuildError(f'{rel}: pass the real file name, the {NEW_SUFFIX} suffix is added by the tool')
        if key in REFUSED:
            raise BuildError(f'{rel}: {REFUSED[key]}')
        if key in WARNED:
            warnings.append(f'{rel}: {WARNED[key]}')
        if options.client_root is not None and not (options.client_root / rel).is_file():
            message = f'{rel} does not exist in {options.client_root} (new file or wrong path)'
            if options.require_existing:
                raise BuildError(message)
            warnings.append(message)
    duplicates = duplicate_basenames([PackageFile(r, p, '') for r, p in inputs.items()])
    if duplicates:
        warnings.append('same file name in more folders, the launcher will skip checksum verification: '
                        + ', '.join(duplicates))
    return warnings


def cgd_base(inputs: dict[PurePosixPath, Path], options: BuildOptions) -> Path | None:
    candidates = [inputs.get(CGD_PATH), product_root(options.tree) / 'Full' / CGD_PATH]
    if options.client_root is not None:
        candidates.append(options.client_root / CGD_PATH)
    return next((c for c in candidates if c is not None and c.is_file()), None)


def build_package(options: BuildOptions, log=print) -> BuildResult:
    patch = current_patch(options.tree)
    source = patch.latest
    target = options.version or source.next()
    new_patch = patch.with_new_version(target)
    inputs = collect_inputs(options.files_dir)
    warnings = check_inputs(inputs, options)
    cab, xml = package_paths(options.tree, source, target)
    if cab.parent.exists():
        raise BuildError(f'{cab.parent} already exists, versions are never rebuilt')
    log(f'(*) {source} -> {target}, {len(inputs)} input files')
    with tempfile.TemporaryDirectory(prefix='tbupdate_') as tmp:
        staging = Path(tmp) / 'files'
        sources = dict(inputs)
        if options.legacy_patch_ini:
            sources[PurePosixPath('patch.ini')] = _write(Path(tmp) / 'patch.ini', new_patch.render())
        if not options.skip_cgd:
            sources[CGD_PATH] = _versioned_cgd(inputs, options, target, Path(tmp), log)
        else:
            warnings.append('cgd.dip not checked: clients are blocked by the game if its pi_version is older than '
                            f'{target}')
        files = _stage(sources, staging)
        cab.parent.mkdir(parents=True)
        try:
            cabinet.create_cab(staging, [PurePosixPath(f.rel_path.as_posix() + NEW_SUFFIX) for f in files], cab,
                               options.compression, log)
            xml.write_bytes(build_manifest(files, str(target), PRODUCT))
            problems = verify_package(cab, xml, target, options.cgd_password, options.legacy_patch_ini)
            if problems.errors:
                raise BuildError('verification failed:\n  ' + '\n  '.join(problems.errors))
            warnings += problems.warnings
            _save_history(options.tree, target)
            _mirror_repair_files(options.tree, files)
        except BaseException:
            shutil.rmtree(cab.parent, ignore_errors=True)
            raise
    _write(product_root(options.tree) / 'patch.ini', new_patch.render())
    for w in warnings:
        log(f'(!) {w}')
    log(f'(OK) {cab.name} {cab.stat().st_size} bytes, {len(files)} files')
    return BuildResult(source, target, cab, xml, files, warnings)


def history_dir(tree: Path, version: GameVersion) -> Path:
    return tree / '.history' / str(version)


def _save_history(tree: Path, target: GameVersion) -> None:
    saved = history_dir(tree, target)
    shutil.rmtree(saved, ignore_errors=True)
    for rel in [PurePosixPath('patch.ini'), *(PurePosixPath('Full') / r for r in REPAIR_FILES)]:
        current = product_root(tree) / rel
        if current.is_file():
            (saved / rel).parent.mkdir(parents=True, exist_ok=True)
            shutil.copyfile(current, saved / rel)


def drop_latest(tree: Path, version: GameVersion, log=print) -> GameVersion:
    patch = current_patch(tree)
    if patch.latest != version:
        raise BuildError(f'{version} is not the latest version ({patch.latest}), only the latest can be dropped')
    saved = history_dir(tree, version)
    if not (saved / 'patch.ini').is_file():
        raise BuildError(f'no saved state in {saved}')
    for rel in REPAIR_FILES:
        mirror = product_root(tree) / 'Full' / rel
        backup = saved / 'Full' / rel
        if backup.is_file():
            shutil.copyfile(backup, mirror)
    shutil.copyfile(saved / 'patch.ini', product_root(tree) / 'patch.ini')
    shutil.rmtree(product_root(tree) / str(version))
    shutil.rmtree(saved)
    restored = current_patch(tree).latest
    log(f'(OK) dropped {version}, the tree is back at {restored}')
    return restored


def _write(path: Path, text: str) -> Path:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(text.encode('ascii'))
    return path


def _versioned_cgd(inputs, options: BuildOptions, target: GameVersion, tmp: Path, log) -> Path:
    base = cgd_base(inputs, options)
    if base is None:
        raise BuildError('no cgd.dip to update: add data/cgd.dip to the files or pass the client root')
    if options.cgd_password is None:
        raise BuildError('the cgd.dip password is needed to set pi_version (or use --skip-cgd)')
    out = tmp / 'cgd.dip'
    versions = cgd.write_pi_version(base, out, options.cgd_password, str(target))
    log(f'(*) cgd.dip from {base}: pi_version -> {", ".join(f"{k}={v}" for k, v in versions.items())}')
    return out


def _stage(sources: dict[PurePosixPath, Path], staging: Path) -> list[PackageFile]:
    files = []
    for rel, src in sorted(sources.items(), key=lambda kv: kv[0].as_posix().lower()):
        staged = staging / (rel.as_posix() + NEW_SUFFIX)
        cabinet.stage_file(src, staged)
        files.append(PackageFile(rel, staged, adler32_file(staged)))
    return files


def _mirror_repair_files(tree: Path, files: list[PackageFile]) -> None:
    for f in files:
        if f.rel_path in REPAIR_FILES:
            target = product_root(tree) / 'Full' / f.rel_path
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.copyfile(f.source, target)


@dataclass
class Problems:
    errors: list[str] = field(default_factory=list)
    warnings: list[str] = field(default_factory=list)


def verify_package(cab: Path, xml: Path, target: GameVersion, cgd_password: bytes | None = None,
                   legacy_patch_ini: bool | None = None) -> Problems:
    problems = Problems()
    if not cab.is_file() or not xml.is_file():
        problems.errors.append(f'missing {cab.name} or {xml.name}')
        return problems
    manifest = xml.read_bytes()
    version, tree_sums, flat_sums = parse_manifest(manifest)
    if version != str(target):
        problems.errors.append(f'{xml.name}: Version={version}, expected {target}')
    if launcher_checksum_keys(manifest) is None:
        problems.warnings.append(f'{xml.name}: duplicate file names, the launcher skips checksum verification')
    with tempfile.TemporaryDirectory(prefix='tbverify_') as tmp:
        out = Path(tmp)
        cabinet.extract_cab(cab, out)
        extracted = cabinet.list_files(out)
        for rel, path in extracted.items():
            _check_extracted(rel, path, tree_sums, flat_sums, problems)
        expected = {k + NEW_SUFFIX for k in tree_sums}
        missing = sorted(expected - {r for r in extracted})
        if missing:
            problems.errors.append(f'{cab.name}: files listed in the xml but not in the cab: {missing}')
        _check_patch_ini(extracted.get('patch.ini.new'), target, legacy_patch_ini, problems)
        _check_cgd(extracted.get(CGD_PATH.as_posix() + NEW_SUFFIX), target, cgd_password, problems)
    return problems


def _check_extracted(rel: str, path: Path, tree_sums, flat_sums, problems: Problems) -> None:
    if not rel.endswith(NEW_SUFFIX):
        problems.errors.append(f'{rel}: without {NEW_SUFFIX} the launcher would strip the real extension')
        return
    real = rel[:-len(NEW_SUFFIX)]
    checksum = adler32_file(path)
    if tree_sums.get(real) != checksum:
        problems.errors.append(f'{rel}: adler32 {checksum} != xml {tree_sums.get(real)}')
    name = PurePosixPath(rel).name
    if flat_sums and flat_sums.get(name) != checksum:
        problems.errors.append(f'{rel}: launcher checksum entry {flat_sums.get(name)} != {checksum}')


def _check_patch_ini(path: Path | None, target: GameVersion, legacy: bool | None, problems: Problems) -> None:
    if path is None:
        if legacy:
            problems.errors.append('patch.ini.new missing from the cab')
        return
    if legacy is False:
        problems.errors.append('patch.ini.new in the cab: the .NET launcher applies it before the other files, '
                               'a failed step would then look installed')
        return
    inner = parse_patch_ini(path.read_text(encoding='ascii'))
    if inner.latest != target:
        problems.errors.append(f'patch.ini.new latest is {inner.latest}, expected {target}')


def _check_cgd(path: Path | None, target: GameVersion, password: bytes | None, problems: Problems) -> None:
    if path is None:
        problems.warnings.append(f'no data/cgd.dip in the package: the game refuses to start unless the installed '
                                 f'pi_version is already >= {target}')
        return
    if password is None:
        problems.warnings.append('cgd.dip pi_version not checked (no password)')
        return
    for name, value in cgd.read_pi_versions(path, password).items():
        if GameVersion.parse(value).key() < target.key():
            problems.errors.append(f'cgd.dip {name} pi_version {value} < {target}: the game would refuse to start')
